sys_script_client.script:
function onLoad() {
    applyTemplateStateReadonly();
}

function applyTemplateStateReadonly() {
    var state = g_form.getValue('state');

    // Fields to lock after Draft
    var templateFields = [
        'name',
        'table',
        'condition',
        'html_template'
    ];

    // Fields to lock after Validation
    var namingFields = [
        'default_file_name',
        'dynamic_name',
        'script_for_naming'
    ];

    // First reset everything to editable
    setFieldsReadOnly(templateFields, false);
    setFieldsReadOnly(namingFields, false);

    // Draft: everything editable
    if (state == 'draft' || state == '') {
        return;
    }

    // Mapping: lock main template structure fields
    if (state == 'mapping') {
        setFieldsReadOnly(templateFields, true);
        return;
    }

    // Validated / Published / Complete: lock both template fields and naming fields
    if (state == 'validated' || state == 'published' || state == 'complete') {
        setFieldsReadOnly(templateFields, true);
        setFieldsReadOnly(namingFields, true);
        return;
    }
}

function setFieldsReadOnly(fields, readOnly) {
    for (var i = 0; i < fields.length; i++) {
        g_form.setReadOnly(fields[i], readOnly);
    }
}
